// 3. 상대 임포트 (라우트 전용)
import { UserCard } from './-components/user-card'
import { useUsers } from './-hooks/use-users'

// 4. 타입 임포트
import type { User } from '@/types'
import type { UseUsersReturn } from './-hooks/use-users'
```

